  async checkPermission() {
    console.log("fcmTokeniid");
    const enabled = await firebase.messaging().hasPermission();
    if (enabled) {
        this.getToken();
    } else {
        this.requestPermission();
    }
  }

  
    //3
  async getToken() {
    console.log("fcmTokenn");
    //let fcmToken = await AsyncStorage.getItem('fcmToken', value);
    fcmToken = await firebase.messaging().getToken();
    const challenge = database.ref('/fcm_token/');

    challenge.on('child_added', snap => {
        challenge.child(this.props.user.email.split('@')[0]).update({
      username: this.props.user.email.split('@')[0],
      fcmToken: fcmToken
        });
    });
    axios.post('http://api.classcast.in/classcast/fcm/save_fcm_token/', {
           username: this.props.user.email.split('@')[0],
           fcmToken: fcmToken
          })
    console.log("fcmTokenm"+fcmToken);
  }

    //2
  async requestPermission() {
    try {
        await firebase.messaging().requestPermission();
        // User has authorised
        this.getToken();
    } catch (error) {
        // User has rejected permissions
        console.log('permission rejected');
    }
  }
  handleBackPress = () => {
    if (this.props.location.pathname === '/') {
      if (this.state.exitWarning) {
        BackHandler.exitApp();
      }
      else {
        ToastAndroid.show('Press back again to exit the app', ToastAndroid.SHORT);
        this.setState({exitWarning: true});
        setTimeout(() => {
          this.setState({exitWarning: false})
        }, 1000);
        return true;
      }
    }
    return false;
  };
